theme.css:
/* theme: Pressure Cooker | Markets and politics all spiking toward critical thresholds — the 10-year at 5%, oil over $103, and election legal battles escalating — so the design turns up the heat with searing gradients and sharp, clipped type. */
/* layout: hero=split; political-news=banner/grid-2; financial-news=numbered/grid-2; entertainment-news=plain/masonry; music-releases=lede/stack; stock-analysis=stat/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #14100c;
  --paper-alt: #1f1811;
  --ink: #f5e9d8;
  --ink-soft: #d4c4ae;
  --muted: #a08c74;
  --accent: #ff6b35;
  --accent-ink: #1a0f08;
  --rule: #3d2f20;
  --font-display: var(--ff-archivo-black), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
  background:
    radial-gradient(1100px 600px at 100% -10%, rgba(255, 107, 53, 0.14), transparent 65%),
    radial-gradient(900px 500px at -20% 110%, rgba(229, 152, 61, 0.10), transparent 60%),
    var(--paper);
  color: var(--ink-soft);
}

/* Heat-striped hero */
.diary-page[data-hero="split"] .diary-hero {
  position: relative;
  border-bottom: 2px solid var(--accent);
  background:
    repeating-linear-gradient(
      -45deg,
      transparent 0 18px,
      rgba(255, 107, 53, 0.035) 18px 36px
    ),
    var(--paper-alt);
}

.diary-page[data-hero="split"] .diary-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--accent) 20%, var(--accent) 80%, transparent);
}

.diary-page[data-hero="split"] .diary-hero-inner {
  position: relative;
  z-index: 1;
}

.diary-page .diary-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.25rem 0.75rem;
  border: 1px solid var(--accent);
  background: rgba(255, 107, 53, 0.08);
  color: var(--accent);
  letter-spacing: 0.22em;
}

.diary-page .diary-kicker::before {
  content: "▲";
  font-size: 0.6rem;
}

.diary-page .diary-title {
  font-size: clamp(2.6rem, 7vw, 5.5rem);
  letter-spacing: -0.03em;
  text-transform: uppercase;
  line-height: 0.95;
  color: var(--ink);
  -webkit-text-stroke: 1px rgba(245, 233, 216, 0.15);
}

.diary-page .diary-summary {
  font-size: clamp(1.05rem, 1.8vw, 1.25rem);
  color: var(--ink-soft);
  border-left: 3px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-ui);
  font-weight: 700;
  letter-spacing: 0.12em;
}

.diary-page .diary-theme-note {
  font-family: var(--font-ui);
  color: var(--muted);
  font-size: 0.9rem;
}

/* Contents rail */
.diary-page .diary-toc {
  border-bottom: 1px solid var(--rule);
  background: rgba(20, 16, 12, 0.92);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top {
  font-family: var(--font-ui);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 0.8rem;
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
}

.diary-page .diary-toc-number {
  font-family: var(--font-ui);
  color: var(--accent);
  font-weight: 700;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-link {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

/* Section headers — thermal labels */
.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  position: relative;
}

.diary-page .diary-section::before {
  content: "";
  position: absolute;
  top: -1px;
  left: 0;
  width: 3.5rem;
  height: 3px;
  background: var(--accent);
}

.diary-page .diary-section-number {
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 3.4vw, 2.5rem);
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: var(--ink);
}

/* ===== Banner cards — election flashpoints, front and center ===== */
.diary-page [data-section="political-news"] .diary-card--banner .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  overflow: hidden;
  background: var(--paper-alt);
}

.diary-page [data-section="political-news"] .diary-card--banner .diary-card-title {
  background:
    linear-gradient(135deg, rgba(255, 107, 53, 0.25), transparent),
    var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-display);
  font-size: 1.3rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  padding: 1rem 1.25rem;
  border-bottom: 3px solid rgba(26, 15, 8, 0.4);
}

.diary-page [data-section="political-news"] .diary-card--banner .diary-card-body {
  padding: 1.25rem;
  font-size: 1.02rem;
}

.diary-page [data-section="political-news"] .diary-card--banner .diary-card-thread {
  margin: 0 1.25rem 1rem;
}

/* ===== Numbered cards — financial news reads like a ledger of pressure points ===== */
.diary-page [data-section="financial-news"] .diary-card--numbered .diary-card-inner {
  border-left: 2px solid var(--rule);
  padding-left: 1.25rem;
  position: relative;
}

.diary-page [data-section="financial-news"] .diary-card--numbered .diary-card-inner::before {
  content: "";
  position: absolute;
  left: -2px;
  top: 0;
  width: 6px;
  height: 6px;
  background: var(--accent);
}

.diary-page [data-section="financial-news"] .diary-card--numbered .diary-card-index {
  font-family: var(--ff-bebas), sans-serif;
  font-size: 3.2rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--accent);
  opacity: 0.8;
}

/* ===== Plain masonry for entertainment — lighter, airier contrast ===== */
.diary-page [data-section="entertainment-news"] .diary-stories--masonry {
  columns: 2 17rem;
}

.diary-page [data-section="entertainment-news"] .diary-card--plain {
  padding: 0 0.5rem 0.75rem;
}

.diary-page [data-section="entertainment-news"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--ink);
  padding-bottom: 0.4rem;
  border-bottom: 1px solid var(--rule);
}

.diary-page [data-section="entertainment-news"] .diary-card-body {
  font-size: 0.98rem;
  color: var(--ink-soft);
}

/* ===== Lede cards for music — a slow, expansive counterpoint ===== */
.diary-page [data-section="music-releases"] .diary-stories--stack {
  max-width: 52rem;
  gap: 2rem;
}

.diary-page [data-section="music-releases"] .diary-card--lede .diary-card-inner {
  padding: 1.5rem 1.5rem 1.5rem 0;
  border-left: 0;
  border-top: 1px solid var(--rule);
}

.diary-page [data-section="music-releases"] .diary-card-lede {
  border-left-color: var(--accent);
  font-family: var(--font-display);
  font-size: 1.1rem;
  color: var(--ink);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.diary-page [data-section="music-releases"] .diary-card--lede .diary-card-title {
  font-size: 1.6rem;
  color: var(--ink);
}

.diary-page [data-section="music-releases"] .diary-card-body {
  font-size: 1.02rem;
}

/* ===== Stat cards — one big number per index/sector ===== */
.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
  background: var(--paper-alt);
  padding: 1.25rem 1.25rem 1.5rem;
  position: relative;
  overflow: hidden;
}

.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-inner::after {
  content: "";
  position: absolute;
  right: -20px;
  top: -20px;
  width: 70px;
  height: 70px;
  background: radial-gradient(circle, rgba(255, 107, 53, 0.15), transparent 70%);
}

.diary-page [data-section="stock-analysis"] .diary-card-figure {
  font-family: var(--font-display);
  color: var(--accent);
  font-size: clamp(2rem, 10cqi, 3.8rem);
}

.diary-page [data-section="stock-analysis"] .diary-card-title {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--ink);
}

.diary-page [data-section="stock-analysis"] .diary-card-body {
  font-size: 0.95rem;
}

/* ===== Timeline for outlook — the pressure points ahead ===== */
.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner::before {
  width: 2px;
  background: linear-gradient(180deg, var(--accent), var(--rule));
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
  width: 0.875rem;
  height: 0.875rem;
  top: 0.5rem;
  left: -1px;
}

.diary-page [data-section="outlook"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.25rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--ink);
}

.diary-page [data-section="outlook"] .diary-card-body {
  font-size: 1rem;
}

/* Markets sparklines — keep them dark */
.diary-page .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark-line polyline {
  stroke: currentColor;
  fill: none;
  stroke-width: 1.5;
}

/* Body prose refinements */
.diary-page .diary-prose {
  line-height: 1.7;
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: rgba(255, 107, 53, 0.4);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose h3 {
  font-family: var(--font-ui);
  color: var(--ink);
  letter-spacing: 0.16em;
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  color: var(--ink);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

/* Threads */
.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(255, 107, 53, 0.06);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Footer */
.diary-page .diary-footer {
  border-top-color: var(--rule);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Entrance: one subtle fade on sections as they arrive */
.diary-page .diary-section {
  animation: diary-rise 0.6s ease both;
}

@keyframes diary-rise {
  from {
    opacity: 0.4;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .diary-page .diary-section {
    animation: none;
  }
}

/* Dark-theme woven in by the base tokens — a single warm charcoal tone everywhere */
@media (prefers-color-scheme: light) {
  .diary-page {
    --paper: #14100c;
    --paper-alt: #1f1811;
    --ink: #f5e9d8;
    --ink-soft: #d4c4ae;
    --muted: #a08c74;
    --accent: #ff6b35;
    --accent-ink: #1a0f08;
    --rule: #3d2f20;
  }
}
